SELECT sm.id master_id,sm.album_id,sm.title,sm.track,sm.disc,sm.duration,si.id instance_id,si.suffix,si.size,so.id object_id,so.physical_key,se.id entry_id,se.parent_id,se.path FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_objects so ON so.id=si.storage_object_id JOIN storage_entries se ON se.instance_id=si.id WHERE sm.album_id='pending-uploads' AND si.missing=0 AND (instr(se.path,'异色合鸣Chromatic Harmony（wav）/A盘/')=1 OR instr(se.path,'异色合鸣Chromatic Harmony（wav）/B盘/')=1) ORDER BY se.path;
